    """

    def __init__(self, map):
        # Convert map to a list of lists to allow mutability during movement
        self.map = [list(row) for row in map]
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.is_game_over = False
        self.init_game()

    def init_game(self):
        """
        Initialize the game by scanning the map for player, boxes, and targets.
        """
        for r, row in enumerate(self.map):
            for c, char in enumerate(row):
                if char == 'O':
                    self.player_row, self.player_col = r, c
                elif char == 'X':
                    self.boxes.append((r, c))
                elif char == 'G':
                    self.targets.append((r, c))

    def check_win(self):
        """
        Check if all boxes are on target positions.
        """
