class SQLQueryBuilder:
    """
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements. 
    """

    @staticmethod
    def _format_where(where):
        """Helper to format dictionary conditions into SQL string."""
        if not where:
            return ""
        conditions = [f"{k}='{v}'" for k, v in where.items()]
        return " WHERE " + " AND ".join(conditions)

    @staticmethod
    def select(table, columns='*', where=None):
        cols = ", ".join(columns) if isinstance(columns, list) else columns
        query = f"SELECT {cols} FROM {table}"
        query += SQLQueryBuilder._format_where(where)
        return query

    @staticmethod
    def insert(table, data):
        keys = ", ".join(data.keys())
        values = ", ".join([f"'{v}'" for v in data.values()])
        return f"INSERT INTO {table} ({keys}) VALUES ({values})"

    @staticmethod
    def delete(table, where=None):
        query = f"DELETE FROM {table}"
        query += SQLQueryBuilder._format_where(where)
        return query

    @staticmethod
    def update(table, data, where=None):
        set_clause = ", ".join([f"{k}='{v}'" for k, v in data.items()])
        query = f"UPDATE {table} SET {set_clause}"
        query += SQLQueryBuilder._format_where(where)
        return query

