class Statistics3:
    """
    This is a class that implements methods for calculating indicators such as median, mode, correlation matrix, and Z-score in statistics.
    """

    @staticmethod
    def mean(data):
        if not data: return 0.0
        return sum(data) / len(data)

    @staticmethod
    def median(data):
        if not data: return 0.0
        sorted_data = sorted(data)
        n = len(sorted_data)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2.0
        return float(sorted_data[mid])

    @staticmethod
    def mode(data):
        if not data: return []
        counts = {}
        for item in data:
            counts[item] = counts.get(item, 0) + 1
        max_freq = max(counts.values())
        return [k for k, v in counts.items() if v == max_freq]

    @staticmethod
    def standard_deviation(data):
        if not data: return 0.0
        m = Statistics3.mean(data)
        variance = sum((x - m) ** 2 for x in data) / len(data)
        return math.sqrt(variance)

    @staticmethod
    def correlation(x, y):
        n = len(x)
        if n != len(y) or n == 0: return 0.0
        mean_x, mean_y = Statistics3.mean(x), Statistics3.mean(y)
        num = sum((x[i] - mean_x) * (y[i] - mean_y) for i in range(n))
        den = math.sqrt(sum((xi - mean_x) ** 2 for xi in x) * sum((yi - mean_y) ** 2 for yi in y))
        return num / den if den != 0 else 0.0

    @staticmethod
    def correlation_matrix(data):
        n = len(data)
        matrix = [[0.0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                matrix[i][j] = Statistics3.correlation(data[i], data[j])
        return matrix

    @staticmethod
    def z_score(data):
        if not data: return []
        m = Statistics3.mean(data)
        sd = Statistics3.standard_deviation(data)
        if sd == 0: return [0.0 for _ in data]
        return [(x - m) / sd for x in data]

