            raise ValueError("Mode must be either 'heat' or 'cool'")
        self.mode = mode

    def auto_set_mode(self):
        if self.current_temperature < self.target_temperature:
            self.mode = 'heat'
        else:
            self.mode = 'cool'

    def auto_check_conflict(self):
        # Check if current mode is logically inconsistent with temperature goals
        if (self.current_temperature < self.target_temperature and self.mode == 'cool') or \
           (self.current_temperature > self.target_temperature and self.mode == 'heat'):
            self.auto_set_mode()
            return False
        return True

    def simulate_operation(self):
        self.auto_set_mode()
        time_elapsed = 0

        # Adjust temperature until it reaches target
        while self.current_temperature != self.target_temperature:
            if self.mode == 'heat':
                self.current_temperature += 1
                # Prevent overshooting
                if self.current_temperature > self.target_temperature:
                    self.current_temperature = self.target_temperature
            else:
                self.current_temperature -= 1
                # Prevent overshooting
                if self.current_temperature < self.target_temperature:
                    self.current_temperature = self.target_temperature

            time_elapsed += 1

        return time_elapsed

