class TriCalculator:
    """
    The class allows to calculate trigonometric values, including cosine, sine, and tangent, using Taylor series approximations.
    """

    def __init__(self):
        pass

    def factorial(self, a):
        """Calculate the factorial of a."""
        if a == 0 or a == 1:
            return 1
        res = 1
        for i in range(2, a + 1):
            res *= i
        return res

    def taylor(self, x, n):
        """Finding the n-order Taylor expansion value of cos (x/180 * pi)."""
        rad = (x * pi) / 180
        result = 0
        for k in range(n):
            # Taylor series for cos(x) = sum((-1)^k * x^(2k) / (2k)!)
            term = ((-1)**k * (rad**(2 * k))) / self.factorial(2 * k)
            result += term
        return result

    def cos(self, x):
        """Calculate the cos value of the x-degree angle."""
        # Normalize angle to range [0, 360]
        x = x % 360
        return self.taylor(x, 50)

    def sin(self, x):
        """Calculate the sin value of the x-degree angle."""
        # sin(x) = cos(90 - x)
        return self.cos(90 - x)

    def tan(self, x):
        """Calculate the tan value of the x-degree angle."""
        # tan(x) = sin(x) / cos(x)
        c = self.cos(x)
        if abs(c) < 1e-15:  # Handle division by near-zero
            raise ValueError("Tangent is undefined for this angle.")
        return self.sin(x) / c

