class VectorUtil:
    """
    The class provides vector operations, including calculating similarity, 
    cosine similarities, average similarity, and IDF weights.
    """

    @staticmethod
    def similarity(vector_1, vector_2):
        # Normalize vectors to unit length and take the dot product
        v1 = matutils.unitvec(vector_1)
        v2 = matutils.unitvec(vector_2)
        return np.dot(v1, v2)

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        # Convert to numpy array if it's a list
        vectors_all = np.array(vectors_all)
        # Normalize the single vector
        v1 = matutils.unitvec(vector_1)
        # Normalize all vectors in the matrix
        v_all = matutils.corpus2dense([matutils.unitvec(v) for v in vectors_all], len(vectors_all)).T
        return np.dot(v_all, v1)

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        # Calculate the mean vector for each list
        mean_1 = np.mean(vector_list_1, axis=0)
        mean_2 = np.mean(vector_list_2, axis=0)
        # Return similarity between the two centroids
        return VectorUtil.similarity(mean_1, mean_2)

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        # Apply the formula log((total_num + 1) / (count + 1))
        idf_dict = {}
        for key, count in number_dict.items():
            idf_dict[key] = np.log((total_num + 1) / (count + 1))
